#include <algorithm>
#include <chrono>
#include <cstdio>
#include <cstdlib>
#include <fstream>
#include <vector>
#include <cstring>
#include "../reshapeKVCache-cuda/utils.h"
#include "../reshapeKVCache-cuda/kernels.h"
#define CK(x) do{auto s=(x);if(s!=cudaSuccess){fprintf(stderr,"CUDA %s\n",cudaGetErrorString(s));exit(2);}}while(0)
template<class T> std::vector<T> rd(const char*name){std::ifstream f(name,std::ios::binary|std::ios::ate);if(!f)exit(3);auto n=f.tellg();std::vector<T>a((size_t)n/sizeof(T));f.seekg(0);f.read((char*)a.data(),n);return a;}
int main(int argc,char**argv){int B=atoi(argv[1]),x=atoi(argv[2]);const int N=1024,H=32,D=128,R=1000,T=512;size_t Q=(size_t)N*H*D;auto k=rd<float>("study_key_f32.bin"),v=rd<float>("study_value_f32.bin"),sc=rd<float>("study_scales_f32.bin");auto slots=rd<int64_t>("study_slot_i64.bin");char fn[100];sprintf(fn,"study_expected_B%d_x%d_u8.bin",B,x);auto exp=rd<uint8_t>(fn);float *dk,*dv;int64_t*ds;uint8_t *dc,*de;CK(cudaMalloc(&dk,Q*4));CK(cudaMalloc(&dv,Q*4));CK(cudaMalloc(&ds,N*8));CK(cudaMalloc(&dc,Q));CK(cudaMalloc(&de,Q));CK(cudaMemcpy(dk,k.data(),Q*4,cudaMemcpyHostToDevice));CK(cudaMemcpy(dv,v.data(),Q*4,cudaMemcpyHostToDevice));CK(cudaMemcpy(ds,slots.data(),N*8,cudaMemcpyHostToDevice));CK(cudaMemset(dc,0,Q));CK(cudaMemset(de,0,Q));auto launch=[&](){reshape_and_cache_kernel<float,uint8_t,Fp8KVCacheDataType::kFp8E4M3><<<N,T>>>(dk,dv,dc,de,ds,H*D,H*D,H,D,B,x,sc[0],sc[1]);};for(int i=0;i<30;i++)launch();CK(cudaDeviceSynchronize());std::vector<uint32_t> prefix(2*Q+N+9);memcpy(prefix.data(),k.data(),Q*4);memcpy(prefix.data()+Q,v.data(),Q*4);size_t at=2*Q;for(auto s:slots)prefix[at++]=s;memcpy(prefix.data()+at,sc.data(),8);at+=2;for(int a:{N,H,D,B,x,R,T})prefix[at++]=a;bool all=true;
for(int trial=1;trial<=5;trial++){CK(cudaDeviceSynchronize());auto a=std::chrono::steady_clock::now();for(int r=0;r<R;r++)launch();CK(cudaDeviceSynchronize());double sec=std::chrono::duration<double>(std::chrono::steady_clock::now()-a).count()/R;std::vector<uint8_t> got(2*Q);CK(cudaMemcpy(got.data(),dc,Q,cudaMemcpyDeviceToHost));CK(cudaMemcpy(got.data()+Q,de,Q,cudaMemcpyDeviceToHost));bool ok=got==exp;uint32_t ma=0;for(size_t i=0;i<got.size();i++){ok&=(got[i]&127)!=127;ma=std::max(ma,(uint32_t)abs((int)got[i]-(int)exp[i]));}all&=ok;std::vector<uint32_t> out=prefix;out.insert(out.end(),got.begin(),got.end());std::string path=std::string(getenv("STUDY_OUTPUT_DIR"))+"/output_trial"+std::to_string(trial)+".bin";std::ofstream f(path,std::ios::binary);f.write((char*)out.data(),out.size()*4);f.close();printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%u,\"max_rel_error\":%.12g,\"error_metric_domain\":\"exact_finite_FP8_encoding_and_cache_layout\",\"timing_region\":\"kernel_launch_loop_per_internal_repeat\",\"jit_excluded\":true,\"internal_repeats\":1000,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"uint32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,sec,ok?"true":"false",got.size(),ma,ma?1.:0.,path.c_str(),out.size());fflush(stdout);}return all?0:1;}
